	reg [AW_FIFO_WIDTH-1:0] aw_fifo [0:FIFO_DEPTH-1];
	reg [FIFO_PTR_WIDTH:0] aw_wr_ptr, aw_rd_ptr;
	wire aw_full = (aw_wr_ptr[FIFO_PTR_WIDTH] != aw_rd_ptr[FIFO_PTR_WIDTH]) && 
