	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			aw_wr_ptr <= 0;
		else if (S_AXI_AWVALID && S_AXI_AWREADY)
			aw_wr_ptr <= aw_wr_ptr + 1;
	end

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			;
		else if (S_AXI_AWVALID && S_AXI_AWREADY) begin
			aw_fifo[aw_wr_ptr[FIFO_PTR_WIDTH-1:0]] <= {
				S_AXI_AWID,
				S_AXI_AWADDR,
				S_AXI_AWLEN,
				S_AXI_AWSIZE,
				S_AXI_AWBURST,
				S_AXI_AWLOCK,
				S_AXI_AWCACHE,
				S_AXI_AWPROT,
				S_AXI_AWQOS
			};
		end
	end

