	reg [AW_FIFO_WIDTH-1:0] aw_m_reg;
	reg aw_m_valid;

	always @(posedge M_AXI_ACLK or negedge m_resetn) begin
		if (!m_resetn) begin
			aw_rd_ptr <= 0;
			aw_m_valid <= 1'b0;
			aw_m_reg <= 0;
		end
		else begin
			if (aw_m_valid && M_AXI_AWREADY) begin
				aw_m_valid <= 1'b0;
			end
			if (!aw_m_valid && !aw_empty) begin
				aw_m_reg <= aw_fifo[aw_rd_ptr[FIFO_PTR_WIDTH-1:0]];
				aw_m_valid <= 1'b1;
				aw_rd_ptr <= aw_rd_ptr + 1;
			end
		end
	end

	assign M_AXI_AWID = aw_m_reg[AW_FIFO_WIDTH-1 : AW_FIFO_WIDTH-C_S_AXI_ID_WIDTH];
	assign M_AXI_AWADDR = aw_m_reg[AW_FIFO_WIDTH-C_S_AXI_ID_WIDTH-1 : AW_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH];
	assign M_AXI_AWLEN = aw_m_reg[AW_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-1 : AW_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8];
	assign M_AXI_AWSIZE = aw_m_reg[AW_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-1 : AW_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3];
	assign M_AXI_AWBURST = aw_m_reg[AW_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-1 : AW_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2];
	assign M_AXI_AWLOCK = aw_m_reg[AW_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1];
