	reg [W_FIFO_WIDTH-1:0] w_fifo [0:FIFO_DEPTH-1];
	reg [FIFO_PTR_WIDTH:0] w_wr_ptr, w_rd_ptr;
	wire w_full = (w_wr_ptr[FIFO_PTR_WIDTH] != w_rd_ptr[FIFO_PTR_WIDTH]) && 
