	end

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			;
		else if (S_AXI_WVALID && S_AXI_WREADY) begin
			w_fifo[w_wr_ptr[FIFO_PTR_WIDTH-1:0]] <= {
				S_AXI_WDATA,
