		end
	end

	// W Channel: M side output
	reg [W_FIFO_WIDTH-1:0] w_m_reg;
	reg w_m_valid;

	always @(posedge M_AXI_ACLK or negedge m_resetn) begin
		if (!m_resetn) begin
			w_rd_ptr <= 0;
			w_m_valid <= 1'b0;
			w_m_reg <= 0;
		end
		else begin
			if (w_m_valid && M_AXI_WREADY) begin
				w_m_valid <= 1'b0;
			end
			if (!w_m_valid && !w_empty) begin
				w_m_reg <= w_fifo[w_rd_ptr[FIFO_PTR_WIDTH-1:0]];
				w_m_valid <= 1'b1;
				w_rd_ptr <= w_rd_ptr + 1;
			end
		end
	end

	assign M_AXI_WDATA = w_m_reg[W_FIFO_WIDTH-1 : W_FIFO_WIDTH-C_S_AXI_DATA_WIDTH];
	assign M_AXI_WSTRB = w_m_reg[W_FIFO_WIDTH-C_S_AXI_DATA_WIDTH-1 : W_FIFO_WIDTH-C_S_AXI_DATA_WIDTH-(C_S_AXI_DATA_WIDTH/8)];
	assign M_AXI_WLAST = w_m_reg[W_FIFO_WIDTH-C_S_AXI_DATA_WIDTH-(C_S_AXI_DATA_WIDTH/8)-1];
	assign M_AXI_WVALID = w_m_valid;

	// B Channel: M to S
	reg [B_FIFO_WIDTH-1:0] b_fifo [0:FIFO_DEPTH-1];
	reg [FIFO_PTR_WIDTH:0] b_wr_ptr, b_rd_ptr;
	wire b_full = (b_wr_ptr[FIFO_PTR_WIDTH] != b_rd_ptr[FIFO_PTR_WIDTH]) && 
	               (b_wr_ptr[FIFO_PTR_WIDTH-1:0] == b_rd_ptr[FIFO_PTR_WIDTH-1:0]);
	wire b_empty = (b_wr_ptr == b_rd_ptr);

	assign M_AXI_BREADY = !b_full;

	always @(posedge M_AXI_ACLK or negedge m_resetn) begin
		if (!m_resetn)
			b_wr_ptr <= 0;
		else if (M_AXI_BVALID && M_AXI_BREADY)
			b_wr_ptr <= b_wr_ptr + 1;
	end

	always @(posedge M_AXI_ACLK or negedge m_resetn) begin
		if (!m_resetn)
			;
		else if (M_AXI_BVALID && M_AXI_BREADY) begin
			b_fifo[b_wr_ptr[FIFO_PTR_WIDTH-1:0]] <= {
				M_AXI_BID,
				M_AXI_BRESP
			};
		end
	end

	// B Channel: S side output
	reg [B_FIFO_WIDTH-1:0] b_s_reg;
	reg b_s_valid;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			b_rd_ptr <= 0;
			b_s_valid <= 1'b0;
			b_s_reg <= 0;
		end
		else begin
			if (b_s_valid && S_AXI_BREADY) begin
				b_s_valid <= 1'b0;
			end
			if (!b_s_valid && !b_empty) begin
				b_s_reg <= b_fifo[b_rd_ptr[FIFO_PTR_WIDTH-1:0]];
				b_s_valid <= 1'b1;
				b_rd_ptr <= b_rd_ptr + 1;
			end
		end
	end

	assign S_AXI_BID = b_s_reg[B_FIFO_WIDTH-1 : B_FIFO_WIDTH-C_S_AXI_ID_WIDTH];
	assign S_AXI_BRESP = b_s_reg[B_FIFO_WIDTH-C_S_AXI_ID_WIDTH-1 : 0];
	assign S_AXI_BVALID = b_s_valid;

	// AR Channel: S to M
	reg [AR_FIFO_WIDTH-1:0] ar_fifo [0:FIFO_DEPTH-1];
	reg [FIFO_PTR_WIDTH:0] ar_wr_ptr, ar_rd_ptr;
	wire ar_full = (ar_wr_ptr[FIFO_PTR_WIDTH] != ar_rd_ptr[FIFO_PTR_WIDTH]) && 
	               (ar_wr_ptr[FIFO_PTR_WIDTH-1:0] == ar_rd_ptr[FIFO_PTR_WIDTH-1:0]);
	wire ar_empty = (ar_wr_ptr == ar_rd_ptr);

	assign S_AXI_ARREADY = !ar_full;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			ar_wr_ptr <= 0;
		else if (S_AXI_ARVALID && S_AXI_ARREADY)
			ar_wr_ptr <= ar_wr_ptr + 1;
	end

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			;
		else if (S_AXI_ARVALID && S_AXI_ARREADY) begin
			ar_fifo[ar_wr_ptr[FIFO_PTR_WIDTH-1:0]] <= {
				S_AXI_ARID,
				S_AXI_ARADDR,
				S_AXI_ARLEN,
				S_AXI_ARSIZE,
				S_AXI_ARBURST,
				S_AXI_ARLOCK,
				S_AXI_ARCACHE,
				S_AXI_ARPROT,
				S_AXI_ARQOS
			};
		end
	end

	// AR Channel: M side output
	reg [AR_FIFO_WIDTH-1:0] ar_m_reg;
	reg ar_m_valid;

	always @(posedge M_AXI_ACLK or negedge m_resetn) begin
		if (!m_resetn) begin
			ar_rd_ptr <= 0;
			ar_m_valid <= 1'b0;
			ar_m_reg <= 0;
		end
		else begin
			if (ar_m_valid && M_AXI_ARREADY) begin
				ar_m_valid <= 1'b0;
			end
			if (!ar_m_valid && !ar_empty) begin
				ar_m_reg <= ar_fifo[ar_rd_ptr[FIFO_PTR_WIDTH-1:0]];
				ar_m_valid <= 1'b1;
				ar_rd_ptr <= ar_rd_ptr + 1;
			end
