	assign M_AXI_ARID = ar_m_reg[AR_FIFO_WIDTH-1 : AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH];
	assign M_AXI_ARADDR = ar_m_reg[AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-1 : AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH];
	assign M_AXI_ARLEN = ar_m_reg[AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-1 : AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8];
	assign M_AXI_ARSIZE = ar_m_reg[AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-1 : AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3];
	assign M_AXI_ARBURST = ar_m_reg[AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-1 : AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2];
	assign M_AXI_ARLOCK = ar_m_reg[AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1];
	assign M_AXI_ARCACHE = ar_m_reg[AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1-1 : AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1-4];
	assign M_AXI_ARPROT = ar_m_reg[AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1-4-1 : AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1-4-3];
	assign M_AXI_ARQOS = ar_m_reg[AR_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_ADDR_WIDTH-8-3-2-1-4-3-1 : 0];
	assign M_AXI_ARVALID = ar_m_valid;

	// R Channel: M to S
	reg [R_FIFO_WIDTH-1:0] r_fifo [0:FIFO_DEPTH-1];
	reg [FIFO_PTR_WIDTH:0] r_wr_ptr, r_rd_ptr;
	wire r_full = (r_wr_ptr[FIFO_PTR_WIDTH] != r_rd_ptr[FIFO_PTR_WIDTH]) && 
