	end

	// R Channel: S side output
	reg [R_FIFO_WIDTH-1:0] r_s_reg;
	reg r_s_valid;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			r_rd_ptr <= 0;
			r_s_valid <= 1'b0;
			r_s_reg <= 0;
		end
		else begin
			if (r_s_valid && S_AXI_RREADY) begin
				r_s_valid <= 1'b0;
			end
			if (!r_s_valid && !r_empty) begin
				r_s_reg <= r_fifo[r_rd_ptr[FIFO_PTR_WIDTH-1:0]];
				r_s_valid <= 1'b1;
				r_rd_ptr <= r_rd_ptr + 1;
			end
		end
	end

	assign S_AXI_RID = r_s_reg[R_FIFO_WIDTH-1 : R_FIFO_WIDTH-C_S_AXI_ID_WIDTH];
	assign S_AXI_RDATA = r_s_reg[R_FIFO_WIDTH-C_S_AXI_ID_WIDTH-1 : R_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_DATA_WIDTH];
	assign S_AXI_RRESP = r_s_reg[R_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_DATA_WIDTH-1 : R_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_DATA_WIDTH-2];
	assign S_AXI_RLAST = r_s_reg[R_FIFO_WIDTH-C_S_AXI_ID_WIDTH-C_S_AXI_DATA_WIDTH-2-1];
	assign S_AXI_RVALID = r_s_valid;

endmodule
